// State transition: Init -> PreOp
HRESULT CTcComTest::SetObjStateIP(ITComObjectServer* ipSrv, TComInitDataHdr* pInitData)
{
	HRESULT hr = S_OK;

	if (SUCCEEDED(hr))
		hr = CheckInstructionSet(TcMgSdk::InstructionSetExtension::None);
	if (SUCCEEDED(hr))
		hr = SingleInstanceLock({0x1166BC0C, 0x54F5, 0xD00B, {0x80, 0x9A, 0x38, 0x8D, 0xC9, 0x5A, 0x61, 0x5B}});
	if (SUCCEEDED(hr))
	{
		m_ContextInfo[0].OriginalTid = 0;
		m_ContextInfo[0].OriginalSampleTime = 0.001;

	}
	if (SUCCEEDED(hr))
	{
		memset(&(TcModuleOutput.Controller.Error),0,sizeof(TcModuleOutput.Controller.Error));
		memset(&(TcModuleOutput.Plant.TargetTorque),0,sizeof(TcModuleOutput.Plant.TargetTorque));
		TcModuleInput.Controller.ControlInput = 0;
		TcModuleInput.Plant.LoadActualPosition1 = 0;
		TcModuleInput.Plant.MotorActualPosition = 0;
		TcModuleInput.Reference.FeedForward = 0;
		TcModuleInput.Reference.Reference = 0;

	}
	if (FAILED(hr))
		SetObjStatePI();
	return hr;
}

// State transition: PreOp -> SafeOp
HRESULT CTcComTest::SetObjStatePS(TComInitDataHdr* pInitData)
{
	HRESULT hr = S_OK;


	if(SUCCEEDED(hr))
	{
		auto fpCtrl = FpControl(FpCtrlSection::Init);
		::Test_initialize();
		Test_DW.ControlInput_PWORK = &(TcModuleInput.Controller.ControlInput);
		Test_DW.Error_PWORK = &(TcModuleOutput.Controller.Error);
		Test_DW.LoadActualPosition1_PWORK = &(TcModuleInput.Plant.LoadActualPosition1);
		Test_DW.MotorActualPosition_PWORK = &(TcModuleInput.Plant.MotorActualPosition);
		Test_DW.TargetTorque_PWORK = &(TcModuleOutput.Plant.TargetTorque);
		Test_DW.FeedForward_PWORK = &(TcModuleInput.Reference.FeedForward);
		Test_DW.Reference_PWORK = &(TcModuleInput.Reference.Reference);

		if (SUCCEEDED(hr))
			hr = CheckAndAdaptCycleTimes();
		m_Initialized = SUCCEEDED(hr);
		FpRestore(fpCtrl);
	}

	if (FAILED(hr))
		SetObjStateSP();
	return hr;
}

