// State transition: SafeOp -> PreOp
HRESULT CTcComTest::SetObjStateSP()
{
	HRESULT hr = S_OK;

	auto fpCtrl = FpControl(FpCtrlSection::Init);
	FpRestore(fpCtrl);

	m_Initialized = false;

	return hr;
}

// State transition: PreOp -> Init
HRESULT CTcComTest::SetObjStatePI()
{
	HRESULT hr = S_OK;

	auto fpCtrl = FpControl(FpCtrlSection::Init);
	rt_StopDataLogging("Test.mat", Test_M->rtwLogInfo);
	::Test_terminate();

	FpRestore(fpCtrl);
	SingleInstanceRelease();

	return hr;
}

